/** FR : liste ordonnée pour l'affichage d'une palette. / EN: ordered list for a picker. */
export const CLES_ICONES_LOADOUT = Object.keys(ICONES) as CleIconeLoadout[];

export function libelleIconeLoadout(cle: CleIconeLoadout): string {
  return ICONES[cle]?.libelle ?? cle;
}

interface Props {
  cle: CleIconeLoadout;
  taille?: number;
  couleur?: string;
}

export default function IconeLoadout({ cle, taille = 16, couleur = "#b7b3a8" }: Props) {
  const icone = ICONES[cle];
  if (!icone) return null;
  return (
    <svg
      width={taille}
      height={taille}
      viewBox={icone.viewBox}
      fill={couleur}
      role="img"
      aria-label={icone.libelle}
      style={{ flexShrink: 0 }}
    >
      <title>{icone.libelle}</title>
      <path d={icone.d} />
    </svg>
  );
}
